INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vestiges: Fallen Tribes', 'Vestiges: Fallen Tribes is a unique blend of strategy, board game mechanics, and autobattler gameplay. Immerse yourself in a sci-fi world where tribes are battling for water, and your tactical decisions will shape the future. As a tribe leader, you’ll use a deck of cards to summon and command animated units round after round, until you come out on top.' FROM games WHERE igdb_id = 273566 ON CONFLICT (game_id, language_code) DO NOTHING;
