INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'An Amazing Wizard', 'An Amazing Wizard is a 2D fast-paced metroidvania-inspired spell-slinging combat RPG game with detailed pixel art. You play as a wizard from legend, wielding the magic of 7 elements cast by mysterious hands. Enhance your spells and melee weapons, defeat enemies to level up and choose from 250 perks. Discover and equip 250 artifacts, and merge 100 unique spells in any desired order. Collect your lost memories and uncover the hidden truth about this world.' FROM games WHERE igdb_id = 169313 ON CONFLICT (game_id, language_code) DO NOTHING;
