INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unmourned', 'Unmourned is a first person psychological horror game where you play as Jason, a man who moves into a new house only to be haunted by escalating paranormal activities. As the disturbances grow more intense, Jason discovers that the house''s previous owners mysteriously vanished. Driven by terror and desperation, Jason must uncover the truth behind the family’s disappearance and find a way to break the curse that now haunts him. Can he solve the mystery before it''s too late?' FROM games WHERE igdb_id = 330058 ON CONFLICT (game_id, language_code) DO NOTHING;
