INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sultan''s Game', 'Sultan''s Game is a card-based simulation and narrative game, inspired by The One Thousand and One Nights. You are one of the ministers of the mighty Sultan, a fickle, cruel king that treats his subject like pawns of a deadly game for his own pleasure. Forced to make dreadful choices to save your own life, you will have to find a way to survive not just the Sultan’s Game, but its consequences too.' FROM games WHERE igdb_id = 318002 ON CONFLICT (game_id, language_code) DO NOTHING;
