INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Caretaker', 'The Last Caretaker is a thoughtful take on the survival-crafting genre, where every decision you make and every action has a consequence. Immerse yourself in a meticulously crafted world where the fate of humanity rests in your hands. Your mission is clear: recover human seeds, reactivate the Lazarus Complex, and launch the last of humanity to the stars.' FROM games WHERE igdb_id = 333443 ON CONFLICT (game_id, language_code) DO NOTHING;
