INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreams of Another', 'Dreams of Another is a third-person exploration-action game built around the philosophical theme, “No Creation Without Destruction.” Rather than destroying objects by shooting—as in traditional shooting games—here, your shots materialize and create the world. This unconventional mechanic offers a gameplay experience that challenges the norms of the genre and invites players into a whole new dimension.' FROM games WHERE igdb_id = 331205 ON CONFLICT (game_id, language_code) DO NOTHING;
