INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commander Quest', '''Commander Quest'' is a unique roguelike that combines the deck-building card game genre with real-time strategy gameplay. Experience a one-of-a-kind gameplay where cute but brutal fantasy units engage in battle. Think about the synergies between your cards and the interactions between units on the field, and enjoy a game that offers both originality and depth.' FROM games WHERE igdb_id = 294032 ON CONFLICT (game_id, language_code) DO NOTHING;
