INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xenoblade Chronicles X: Definitive Edition', 'The year is 2054. Earth has been destroyed by an intergalactic war between two alien races, and humanity is on the brink of annihilation. A small number of survivors, aboard the USS White Whale, crash land on the vast and untamed planet Mira—and now it falls to you, as a member of BLADE, to help bring humanity back from the edge of extinction…with the aid of powerful giant robots called Skells!
