INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Half of Darkness', 'Your aunt sure was a strange one. She was some sort of witch or something. A good witch though, practicing only good spells and magic. In fact, she was working on a potion just before she was killed. Now the secret will go to the grave with her... unless you can find the missing ingredients.' FROM games WHERE igdb_id = 312756 ON CONFLICT (game_id, language_code) DO NOTHING;
