INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kun’tewiktuk: A Mi’kmaw Adventure', 'Kun’tewiktuk: A Mi’kmaw Adventure is a fantasy adventure game inspired by Mi’kmaw legend and folklore. It chronicles the adventures of siblings Wasuek ("Flower") and her brother U''n ("Fog"). They get separated one summer morning and they go on an adventure through the spirit world to reunite.' FROM games WHERE igdb_id = 303620 ON CONFLICT (game_id, language_code) DO NOTHING;
