INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Just Want to Be Single!!', 'I Just Want To Be Single!! is a visual novel dating simulation game where the twist is that you do not want to date the cast of eligible bachelorettes. In the game, you play as Aya, a socially awkward girl in her second year of high school, who only wants to make friends. Unfortunately, being a new transfer student starts turning heads and gets the attention of everyone in her class.' FROM games WHERE igdb_id = 180571 ON CONFLICT (game_id, language_code) DO NOTHING;
